import{c as p,a1 as n,U as s,h as d,l as a,e as l,m as e,n as r,aw as i}from"./chunks/framework.C0iWzFTI.js";const u="/blog/assets/image-2300230239.Dvov5WBr.png",P="/blog/assets/image-20230516093753818.XNmX1uF6.png",m="/blog/assets/image-20230527003122309.kTGDOo9S.png",c=JSON.parse('{"title":"RPC概述和架构的演变","description":"RPC 基础和设计","frontmatter":{"title":"RPC概述和架构的演变","description":"RPC 基础和设计","tag":["RPC"],"date":"2023-08-12T12:22:16.000Z","tags":["RPC"]},"headers":[],"relativePath":"6-RPC/RPC系列/01.概述.md","filePath":"6-RPC/RPC系列/01.概述.md"}'),b={name:"6-RPC/RPC系列/01.概述.md"};function C(g,t,q,h,R,f){const o=n("font");return s(),d("div",null,[t[14]||(t[14]=a('<h1 id="rpc-概述和架构的演变" tabindex="-1">RPC 概述和架构的演变 <a class="header-anchor" href="#rpc-概述和架构的演变" aria-label="Permalink to &quot;RPC 概述和架构的演变&quot;">​</a></h1><h2 id="一、简介" tabindex="-1">一、简介 <a class="header-anchor" href="#一、简介" aria-label="Permalink to &quot;一、简介&quot;">​</a></h2><h3 id="_1-1-引言" tabindex="-1">1.1 引言 <a class="header-anchor" href="#_1-1-引言" aria-label="Permalink to &quot;1.1 引言&quot;">​</a></h3><p><strong>RPC</strong> 是远程过程调用 （<code>Remote Procedure Call</code>）的缩写形式，是一种跨进程的方法调用形式，是目前在 Java 分布式，微服务体系过程之中，重要的一种通信方式。</p><blockquote><p>在 JVM 中，启动一个项目，就意味着开启了一个线程，这里的跨进程可以理解为：有两个项目在两个虚拟机之中去跑，或者在一个虚拟机之中同时运行。</p></blockquote><p>究竟是那些问题的存在，导致了这种方式的出现呢？下面我们首先来看一下系统架构的演变过程</p><h3 id="_1-2-架构的演变过程" tabindex="-1">1.2 架构的演变过程 <a class="header-anchor" href="#_1-2-架构的演变过程" aria-label="Permalink to &quot;1.2 架构的演变过程&quot;">​</a></h3>',7)),l("p",null,[t[1]||(t[1]=e("在软件开发的时候，最早出现的就是")),r(o,{style:{color:"red"}},{default:i(()=>t[0]||(t[0]=[e("单体架构")])),_:1}),t[2]||(t[2]=e("，就是将系统中所有的功能代码耦合在一起，生成")),t[3]||(t[3]=l("strong",null,"一个 jar（war",-1)),t[4]||(t[4]=e("），部署在")),t[5]||(t[5]=l("strong",null,"一个tomcat",-1)),t[6]||(t[6]=e("之中，是")),t[7]||(t[7]=l("strong",null,"一个JVM进程",-1)),t[8]||(t[8]=e("，就比如下面这个系统一样"))]),t[15]||(t[15]=a('<p><img src="'+u+'" alt=""></p><p>那么这个架构到底存在什么问题呢？下面来进行列举</p><p>1）<code>存在热点问题</code>：这两部分资源都是放在一个jar包里面，跑在一个虚拟机之中，就会出现一个系统的访问量过大，占用了服务器的资源，进而就会影响到另一个系统的访问</p><p>2）<code>扩展性比较差</code>：新资源的分配粒度不精确</p><p>3）<code>模块的耦合性较高</code>：两个模块都是在一个大项目之中去写的，可能会出现，两个模块都依赖于一个Service，如果有一天门户提出了一个新的需求，需要去修改AService，但是后台管理系统不需要或者说不想要这个需求，就会产生影响</p><p>4）<code>维护和部署的成本较高</code>：某一次发布，只更新一部分代码，但是由于是单体架构，所以会发布整个系统</p><p>5）<code>技术栈受限</code>，必须要使用相同的编程语言</p>',7)),l("p",null,[t[10]||(t[10]=e("接下来出现的架构就是：")),l("strong",null,[r(o,{style:{color:"red"}},{default:i(()=>t[9]||(t[9]=[e("单体式架构的水平扩展")])),_:1})]),t[11]||(t[11]=e("，将一个相同的项目，部署到个多个机器之上"))]),t[16]||(t[16]=l("p",null,[l("img",{src:P,alt:"image-20230516093753818"})],-1)),t[17]||(t[17]=l("p",null,"但是这种架构只解决了热点问题，也就是说可以解决单体架构在单台服务器之上，内存，CPU，网络连接数遇到瓶颈时的问题，但是其余的问题还是没有解决掉，",-1)),l("p",null,[l("strong",null,[r(o,{style:{color:"red"}},{default:i(()=>t[12]||(t[12]=[e("垂直结构")])),_:1})]),t[13]||(t[13]=e("，把一个单体架构的应用，按照子系统进行划分，每个子系统都部署在自己的 tomcat 之中，多个子系统共享数据库等存储资源，有限的解决了单体架构的问题。当我们的系统通过垂直架构来进行划分之后，比如说现在已经拆分出来两个模块，模块A 和 模块B，如果说现在模块A要实现一个功能点C，但是这个功能在模块B之中已经存在了，所以现在就有两种策略："))]),t[18]||(t[18]=a('<ul><li>方式一：在模块A之中，再实现一波功能C</li><li>方式二：调用模块B的这个功能</li></ul><p>对于这两种方式，使用方式二能够使得系统的内聚性更高。</p><blockquote><p>模块内部的各个元素之间的关联更加紧密，即所谓的高内聚性，模块的内聚性越高，其模块化的效果就会越好，软件的可维护性、可扩展性和可重用性也会更加优秀。</p></blockquote><p>而方式二，由一个模块调用另一个模块的功能，也就是所说的 <strong>RPC</strong>。</p><p>到这里为止，我们就看了一下整体架构的演变过程，那么我们该如何去设计一个 RPC 框架呢？</p><h2 id="二、rpc-的设计" tabindex="-1">二、RPC 的设计 <a class="header-anchor" href="#二、rpc-的设计" aria-label="Permalink to &quot;二、RPC 的设计&quot;">​</a></h2><h3 id="_2-1-设计目标" tabindex="-1">2.1 设计目标 <a class="header-anchor" href="#_2-1-设计目标" aria-label="Permalink to &quot;2.1 设计目标&quot;">​</a></h3><p>对于一个RPC框架，它的设计目标就是：让调用者像调用本地方法一样调用远端的服务方法。</p><p>为了实现这个目标，究竟需要解决那些问题？</p><h3 id="_2-2-核心问题" tabindex="-1">2.2 核心问题 <a class="header-anchor" href="#_2-2-核心问题" aria-label="Permalink to &quot;2.2 核心问题&quot;">​</a></h3><p>RPC 是 两个模块之间进行跨进程调用，首先需要解决的就是通信方式</p><h4 id="_01-通信方式" tabindex="-1">01 通信方式 <a class="header-anchor" href="#_01-通信方式" aria-label="Permalink to &quot;01 通信方式&quot;">​</a></h4><p>两个模块在不同的虚拟机上，就会涉及到了跨进程的调用，跨进程调用可以走网络，进行网络编程，这里就会涉及到了协议的选择，使用 Http 协议？ 还是使用 TCP协议 ？</p><blockquote><p>Http 底层虽然也是 TCP，但是走Http协议，会在消息头加上Http相关信息</p><p>Http 是短连接协议 （即时到后面也是有限的长连接），需要频繁的建立 和关闭连接</p></blockquote><p>那么走两种协议究竟会带来哪些优点，哪些缺点？</p><p><strong>1）如果走 HTTP 协议</strong></p><ul><li>使用HTTP协议，最为方便的是不用开发服务器，有现成的，如Tomcat，Resin。</li><li>服务器端，不能够直接通过网络进行调用Service，需要通过控制器进行暴露。</li><li>客户端发起 Http 请求，可以使用HttpClient，RestTemplate，WebClient，OKHttp</li><li>优势：文本类型 字符串协议，跨语言平台好</li><li>问题：传输数据量大</li><li>典型的技术实现方案：Spring Clout Feign ；Hessian RPC</li></ul><p><strong>2）如果走 TCP 协议</strong></p><ul><li>服务器端需要自己开发 Socket 编程，接受客户端传递过来的参数，不过可以直接调用 Service 进行使用，</li><li>优势：效率高，连接的复用性较好。自己定义应用协议。自己定义序列化的方式</li><li>问题：开发难度增大，对使用者不友好</li><li>典型的技术实现方案：Dubbo</li></ul><h4 id="_02-协议" tabindex="-1">02 协议 <a class="header-anchor" href="#_02-协议" aria-label="Permalink to &quot;02 协议&quot;">​</a></h4><p>如果使用 TCP ，需要自定义协议。如果说我们自定义协议，将会包含两大部分：</p><ul><li>协议头</li><li>协议体</li></ul><h4 id="_03-序列化" tabindex="-1">03 序列化 <a class="header-anchor" href="#_03-序列化" aria-label="Permalink to &quot;03 序列化&quot;">​</a></h4><p>在网络通信之中，序列化是必不可少的一环。他相当于通信双方定义的一种标准，对数据进行处理。</p><p>发送方在发送的时候，将数据通过<code>序列化</code>操作转换为一种格式，接受方在接受之中，在将这种格式的数据通过<code>反序列化</code>转为原来的样子。</p><p>根据序列化之后的数据格式，可以分为以下两种：</p><ul><li>文本格式的序列化实现方案：数据通过某种格式通过文本的格式呈现；目前最为广泛使用是<code>JSON</code>格式和<code>XML</code>格式</li><li>二进制格式的序列化实现方案：数据通过某种编排规则通过二进制格式呈现；但是这种方式对于异构性语言并不友好</li></ul><p>由于序列化的最终目的是为了进行网络传输，所以选择一种比较好的序列化方式，让内容转换之后尽可能的小，就显得尤为重要了。</p><h4 id="_04-远程代理类" tabindex="-1">04 远程代理类 <a class="header-anchor" href="#_04-远程代理类" aria-label="Permalink to &quot;04 远程代理类&quot;">​</a></h4><p>RPC 的设计目标就是让调用者像调用本地方法那样调用远端方法。在设计的时候，要尽可能屏蔽细节，让适用方只关注业务接口，所以在调用者这方，需要创建远程服务类的代理类。</p><h3 id="_2-3-衍生方案-注册中心" tabindex="-1">2.3 衍生方案 - 注册中心 <a class="header-anchor" href="#_2-3-衍生方案-注册中心" aria-label="Permalink to &quot;2.3 衍生方案 - 注册中心&quot;">​</a></h3><p>当服务端有多个实例的时候，这种情况之下就需要考虑注册中心了，在注册中心之中，有所有服务的注册的信息。</p><p><img src="'+m+'" alt="image-20230527003122309"></p><p>那个这个注册中心究竟有哪些功能呢？</p><p>1）进行负载均衡，基于轮训或者加权的一些策略，将请求达到对应的服务上</p><p>2）进行服务的管理：定期的发送心跳，看那些服务是可以使用的</p><p>3）解耦合：客户端不需要写死服务端的地址，而是从注册中心去获取服务</p><p>4）熔断：如果服务端的这个实例挂了，断开这个连接</p><p>5）限流：限制某一个实例的访问量</p>',39))])}const x=p(b,[["render",C]]);export{c as __pageData,x as default};
